package ai.hamza.edm;

import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Matches against src/test/resources/edm/customers.json, which was generated by
 * scripts/edm-index.py — passing here proves Python-indexer / Java-gate fingerprint
 * parity end to end (normalization + HMAC + serialization).
 */
class EdmMatcherTest {

    private EdmMatcher matcher() throws Exception {
        Path dir = Path.of(getClass().getResource("/edm").toURI());
        return new EdmMatcher(new RegistryStore(dir));
    }

    @Test
    void countsDistinctValuesFromTheFixtureRegistry() throws Exception {
        StringBuilder dump = new StringBuilder("{\"rows\": [");
        for (int i = 1; i <= 12; i++) {
            dump.append("{\"email\": \"fake%03d@example-corp.test\"},".formatted(i));
        }
        dump.append("]}");
        Map<String, Integer> counts = matcher().match(dump.toString());
        assertThat(counts).containsEntry("customers", 12);
    }

    @Test
    void repeatedValueCountsOnce() throws Exception {
        String text = "fake001@example-corp.test fake001@example-corp.test fake001@example-corp.test";
        assertThat(matcher().match(text)).containsEntry("customers", 1);
    }

    @Test
    void emailAfterAssignmentDelimiterMatchesExactRegistryValue() throws Exception {
        EdmCountScanResult result = matcher().scanCounts(
                "owner=fake001@example-corp.test amount=10");

        assertThat(result.complete()).isTrue();
        assertThat(result.counts()).containsEntry("customers", 1);
    }

    @Test
    void shellQuotedEmailMatchesExactRegistryValue() throws Exception {
        EdmCountScanResult result = matcher().scanCounts(
                "./lookup.sh 'fake001@example-corp.test'");

        assertThat(result.complete()).isTrue();
        assertThat(result.counts()).containsEntry("customers", 1);
    }

    @Test
    void twoWordNameMatchesViaTwoGramAndSpacedCardViaDigitRun() throws Exception {
        // "Jane Smith" via the 2-gram; the card via the digit-run 4-gram — spaced and
        // unspaced forms normalize to the same fingerprint, so this counts exactly 2.
        String text = "please call Jane Smith about card 4111 1111 1111 1001";
        assertThat(matcher().match(text)).containsEntry("customers", 2);
    }

    @Test
    void regroupedDigitRunReassemblesUpToFiveTokens() throws Exception {
        // Same 16 card digits split into 5 groups: normalization strips spacing, so any
        // grouping within the run limit must hit the indexed fingerprint.
        assertThat(matcher().match("ref 41 1111 1111 111 001 attached"))
                .containsEntry("customers", 1);
    }

    @Test
    void pairGroupedDigitRunReassemblesAtSixTokens() throws Exception {
        // Pair/triple-grouped account formats need the full MAX_DIGIT_RUN of 6.
        assertThat(matcher().match("acct 411 111 111 111 10 01 ok"))
                .containsEntry("customers", 1);
    }

    @Test
    void letteredTokenBreaksTheDigitRun() throws Exception {
        assertThat(matcher().match("4111 1111 card 1111 1001")).isEmpty();
    }

    @Test
    void innocuousTextMatchesNothing() throws Exception {
        assertThat(matcher().match("deploy the parser and fix the flaky integration test"))
                .isEmpty();
    }

    @Test
    void reportsPathologicallyLongCandidatesWithoutSuppressingNearbyMatches() throws Exception {
        String longToken = "x".repeat(10_000);

        EdmCountScanResult alone = matcher().scanCounts(longToken);
        EdmCountScanResult nearby = matcher().scanCounts(
                longToken + " fake001@example-corp.test");

        assertThat(alone.complete()).isFalse();
        assertThat(alone.counts()).isEmpty();
        assertThat(nearby.complete()).isFalse();
        assertThat(nearby.counts()).containsEntry("customers", 1);
    }

    @Test
    void sparseBoundedTokensSeparatedByLargeWhitespaceRemainComplete() throws Exception {
        EdmCountScanResult result = matcher().scanCounts(
                "prefix " + " ".repeat(1024 * 1024) + "fake001@example-corp.test");

        assertThat(result.complete()).isTrue();
        assertThat(result.counts()).containsEntry("customers", 1);
    }
}
